import { z } from 'zod';

/**
 * OmniCard: 萬能分身核心原子單位契約
 * 遵循 5T 協議（Traceable, Transparent, Tangible, Trackable, Trustworthy）
 */
export const OmniCardSchema = z.object({
  uuid: z.string().uuid().describe('唯一事件溯源 ID (Traceable)'),
  name: z.string().min(1).describe('牌名'),
  attributes: z.array(z.string()).describe('屬性集合 (10 色元素法則)'),
  abilities: z.array(z.string()).describe('功能模組代碼'),
  status: z.enum(['todo', 'doing', 'done']).describe('卡牌狀態'),
  lastUpdated: z.number().int().positive().describe('Vector Clock / 時間戳 (Trackable)'),
});

export type OmniCard = z.infer<typeof OmniCardSchema>;

export interface NotionPagePayload {
  id: string;
  url: string;
  last_edited_time: string;
  properties: Record<string, unknown>;
}

/**
 * OmniEvent: 全域處理日誌 (GPL) 事件契約
 * 實現 Event Sourcing 與 Hash Lock 審查
 */
export const OmniEventSchema = z.object({
  id: z.string().uuid().describe('事件唯一 ID'),
  omni_card_uuid: z.string().uuid().describe('對應的 OmniCard 溯源 ID'),
  event_type: z.string().min(1).describe('事件類型 (e.g., CARD_SYNCED)'),
  payload: OmniCardSchema.describe('轉換後的 OmniCard 資料或增量修改'),
  source_platform: z.string().min(1).describe('來源平台 (e.g., Notion)'),
  created_at: z.number().int().positive().describe('發生時間戳 (Traceable)'),
  hash_lock: z.string().min(64).describe('防篡改哈希鎖 SHA-256 (Trustworthy)'),
  cryptographic_seal: z.string().optional().describe('ZKP 零知識證明與密碼學封印 (Trustworthy)'),
});

export type OmniEvent = z.infer<typeof OmniEventSchema>;
